  --dg-bronze: #6e4a22;
  --dg-parchment: #e9d2a6;
  --dg-parchment-shade: #cfae7a;
  --dg-ink-text: #3a2110;
  --dg-ink-soft: #5c3a1e;
  --dg-rubric: #7c2216;
  --dg-text: #e8dcc4;
  --dg-text-strong: #f6ead2;
  --dg-text-muted: #a8977c;
  --dg-text-faint: #7a6b57;
  --dg-hp: #c4372f;
  --dg-mp: #4f8fe0;
