  --dg-font-serif: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', 'SimSun', serif;
  --dg-font-data: 'Cinzel', 'Noto Serif SC', serif;
  --dg-font-ui: 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', sans-serif;
  --dg-asset-base: 'https://img.vinsimage.org/%E5%9C%B0%E7%89%A2/%E7%B4%A0%E6%9D%90%E5%BA%93/%E9%80%9A%E7%94%A8UI';
